/* Estonian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jaan": "God is gracious — Hebrew Yohanan", "Mari": "The classic Estonian feminine name.", "Peeter": "rock, stone — Greek petros", "Kadri": "pure — Greek Katherine", "Mati": "gift of God — Hebrew Matthew", "Liisa": "God is my oath — Hebrew Elisheva", "Tamm": "A classic nature surname.", "Magi": "A classic nature surname.", "Kask": "A classic nature surname.", "Rebane": "A beloved animal surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jaan';
console.log(lookup(q));

